@Component("stockAdjustment-handler")
@ProcessingGroup("stockAdjustment-processing-group")
public class StockAdjustmentEventHandler {
	
	// core constructor
	StockAdjustmentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateStockAdjustmentEvent
     */
    @EventHandler
    public void handle( CreateStockAdjustmentEvent event) {
        entityManager.persist(new StockAdjustment(event.getStockAdjustmentId(), event.getAdjustmentNumber(), event.getReason(), event.getAdjustmentDate(), event.getWarehouse(), event.getLines(), event.getTransactions(), event.getAdjustmentType(), event.getStatus()));
    }

    /*
     * @param	event UpdateStockAdjustmentEvent
     */
    @EventHandler
    public StockAdjustment handle( UpdateStockAdjustmentEvent event) {
    	entityManager.merge(new StockAdjustment(event.getStockAdjustmentId(), event.getAdjustmentNumber(), event.getReason(), event.getAdjustmentDate(), event.getWarehouse(), event.getLines(), event.getTransactions(), event.getAdjustmentType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteStockAdjustmentEvent
     */
    @EventHandler
    public void on( DeleteStockAdjustmentEvent event) {
    	StockAdjustment entity = new StockAdjustment();
   
    	// ------------------------------------------
    	// apply the StockAdjustmentId
    	// ------------------------------------------
    	entity.setStockAdjustmentId( event.getStockAdjustmentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final StockAdjustmentRepository stockAdjustmentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(StockAdjustmentEventHandler.class.getName());

}
